// mensagem que retoma o atendimento parado: pergunta só o próximo passo que falta (mesma ordem do funil da visita)
function textoRetomada(c) {
  const d = (c && c.dados) || {};
  const nome = nomeDeTratamento(d.nome), ola = nome ? nome + ', ' : '';
  if (ORCAMENTO_AUTO.includes(d.interesse)) {
    const f = proximaFalta(d);
    const q = f === 'cor' ? 'qual pedra você prefere' : f === 'pecas' ? 'as medidas e a quantidade das peças' : (f === 'acabamento' || f === 'acabamento2') ? 'qual acabamento você prefere' : '';
    return q ? `${ola}${ola ? 'f' : 'F'}alta só mais um detalhe para eu preparar o seu orçamento: ${q}. Pode me responder quando quiser.` : '';
  }
  let q;
  if (!d.cor) q = 'qual pedra ou cor você deseja';
  else if (!d.endereco) q = 'a sua localização atual no local da obra (pelo clipe no Android ou pelo + no iPhone, em "Localização" > "Enviar sua localização atual") ou o endereço completo';
  else if (!d.horario || !/^\d{4}-\d{2}-\d{2}$/.test(String(d.visita_dia || ''))) q = 'o melhor dia e horário para a visita';
  else q = 'se o resumo da visita está certo';
  return `${ola || ''}${ola ? 'f' : 'F'}icou faltando só um passo para deixar a sua visita técnica combinada: ${q}. Pode me responder quando quiser.`;
}
