  await pontoAvisarDono(env, `⚠️ *${r.cli}* disse que teve um problema com ${r.serv.replace(/\b(sua|seu) /, '')} (entregue em ${dataBR(r.entrega)}). Pedi detalhes e foto.\nwa.me/${normalizarBR(from)}`).catch(() => {});
  return true;
