  if (etapa === 'instalacao' || etapa === 'entrega' || etapa === 'retirada') { ped.entregueEm = ped.entregueEm || ts; ped.entFeitoPor = ped.entFeitoPor || ids[0]; if (!ped.fabProntoEm) ped.fabProntoEm = ts; }
