  const ini = semIni(hoje), a = await analiseEquipe(env, ini, hoje, { cfg, peds, tot, memo, semPonto: true }), b = await analiseEquipe(env, isoSomaDias(ini, -28), isoSomaDias(ini, -1), { cfg, peds, tot, memo, semPonto: true });
