    const ms = (await env.HR_DB.prepare("SELECT ts, texto FROM crm_msg WHERE num = ? AND q = 'c' AND tipo IN ('text', 'audio') AND ts > ? ORDER BY ts").bind(String(g0.num), Date.now() - 5 * 86400000).all()).results || [];
