    input_schema: { type: 'object', properties: { cliente: { type: 'string', description: 'nome (ou parte) do cliente; vazio para todos' }, filtro: { type: 'string', enum: ['a_receber', 'entregues', 'todos'], description: 'a_receber = entregues com saldo em aberto (padrão sem cliente)' } } },
