async function vdCfg(env) { let c = {}; try { c = JSON.parse((await env.HR_KV.get('vd:cfg')) || '{}'); } catch (_) {} return { ligado: c.ligado !== false && String(env.VIDEO_DIA || '1') !== '0', hora: Number.isFinite(c.hora) ? c.hora : (Number(env.VIDEO_DIA_HORA) || 8) }; }
