        if (j0.estado === 'na_fila') { await estGravar(env, j0); await enviar(env, from, 'Anotado para o post: ' + (d.length >= 6 ? `"${d.slice(0, 80)}"` : EST_DESTINOS[j0.destino])); return true; }
