    if (p === '/ponto/icone.png') return new Response(Uint8Array.from(atob(PONTO_ICONE_PNG), c => c.charCodeAt(0)), { headers: { 'Content-Type': 'image/png', 'Cache-Control': 'public, max-age=86400' } }); // v35
    if (p === '/ponto/icone.svg') return new Response('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><rect width="512" height="512" rx="110" fill="#141415"/><circle cx="256" cy="256" r="150" fill="none" stroke="#c4a46a" stroke-width="28"/><path d="M256 170v95l60 40" fill="none" stroke="#ecd5a3" stroke-width="28" stroke-linecap="round"/></svg>', { headers: { 'Content-Type': 'image/svg+xml', 'Cache-Control': 'public, max-age=86400' } });
    if (p === '/ponto/sw.js') return new Response(PONTO_SW, { headers: { 'Content-Type': 'application/javascript', 'Cache-Control': 'no-cache' } });
    if (p === '/ponto/hora') return J({ ts: Date.now() });
